	public static AnimationDefinition of(SeraphAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case WALK -> WALK;
			case INTRO -> INTRO;
			case WINGS -> WINGS;
			case FIRE -> FIRE;
			case COAL -> COAL;
			case GLORIA -> GLORIA;
			case TURNING -> TURNING;
			case HOST -> HOST;
			case STAGGER -> STAGGER;
			case PHASE -> PHASE;
			case HURT -> HURT;
			case DEATH -> DEATH;
		};
	}

	/** Every animation, in SeraphAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(SeraphAnim.values()).map(SeraphAnimations::of).toList();
	}
